{
  "case_id": "xsu_sg_006_work_history_information",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Punkterne 1, 2 og 4 stemmer med kilden. Punkt 3 gengiver forkert, at oplysninger om erhvervsarbejde før ansøgningen bruges, som om de altid indgår. Kilden siger, at de 'kan indgå', navnlig når ophøret skyldtes andre forhold og funktionsnedsættelsen ikke er forværret. Svaret nævner ikke denne særlige situation. Det afsluttende afsnit er mere en formålsangivelse end en forkert påstand."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret dækker Skattestyrelsens oplysninger, ansøgerens egne oplysninger og arbejde under studiet. Det kritiske element om, at tidligere arbejde navnlig er relevant, når ophøret skyldtes andre forhold end funktionsnedsættelsen, og denne ikke er forværret efter ophøret, mangler."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret er en direkte opremsning af de oplysninger om arbejde og indkomst, der bruges i erhvervsevnevurderingen, og besvarer dermed spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, vejledningsafsnit eller lignende."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Indholdet svarer i det væsentlige til vejledningspassagen. Henvisningen til 'varig fysisk eller psykisk funktionsnedsættelse' og 'meget betydelige begrænsninger' i sidste afsnit støttes af SU-lovens § 7, stk. 3. Der tilføjes ingen ny regel, betingelse eller myndighed."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Forbeholdet 'kan indgå' og 'navnlig' for tidligere arbejde er udeladt. Svaret nævner heller ikke, at oplysningerne indgår i en samlet vurdering og ikke alene afgør retten."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Opremsningen er konsistent med sig selv, og afslutningen følger af den. Der er ingen indre modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Punkt 3 gengiver 'kan indgå' som en fast, generel brug af oplysninger om tidligere erhvervsarbejde. Det gør en skønsmæssig og ikke-absolut regel for firm."
    }
  },
  "xhaile_coverage": {
    "A18": {
      "label": "yes",
      "reason": "Svaret nævner, at oplysninger om arbejdstimer og indkomst indhentes fra Skattestyrelsen."
    },
    "A19": {
      "label": "yes",
      "reason": "Svaret nævner ansøgerens egne oplysninger om tidligere arbejdsforhold, som skal angives i ansøgningen."
    },
    "A20": {
      "label": "partial",
      "reason": "Svaret nævner erhvervsarbejde før ansøgningen og under studiet. Det udelader 'kan'-formuleringen og den særlige situation, hvor ophøret skyldes andre forhold, og funktionsnedsættelsen ikke er forværret."
    }
  },
  "overall_notes": "Svaret er kort og i det store hele korrekt i sin gengivelse af kilden. Det udelader dog det kritiske element om tidligere arbejde ('navnlig' når ophøret skyldtes andre forhold og ingen forværring) og de nødvendige forbehold ('kan indgå', samlet vurdering). Svaret angiver ingen kilder."
}

